(function($) {

    $("noc").each(function( index ) {

	// nocbox plugin class or id
	var nocbox = null;
	nocbox = $(this).attr("class");

	// make it class-ish
	if (nocbox) nocbox = '.' + nocbox;
	else {
	    nocbox = $(this).attr("id");
	    // make it id-ish
	    if (nocbox) nocbox = '#' + nocbox;
	}

	// node id which supported
	var nid = $(this).attr("nid");

	// node name yet supported
	var name = $(this).attr("name");

	// any type else supported
	var type = $(this).attr("type");
	switch(type) {
	    case 'xml':
		type = 'xml';
		break;
	    case 'json':
		type = 'json';
		break;
	    case 'script':
		type = 'script';
		break;
	    default:
		type = 'html';
		break;
	}

	if (nid) {
	    // it's free to move this condition upward
	    if (nocbox != null) {

		console.log(name + ": "  + type);

		$.ajax({
		    url: '/nid/',
		    type: 'POST',
		    dataType: type,
		    data: {
			nid: nid,
			name: name,
			noctype: type
		    },
		    success:function (data) {

			var len = jQuery.trim( data ).length;

			console.log(name + ": " + len);

			if (len) {
			    $("noc")
			    .eq(index)
			    .html(data)
			    .fadeIn('fast');
			} else {
			    $("noc")
			    .eq(index)
			    .addClass('ui-state-error ui-corner-all')
			    .css("padding","6px")
			    .html("Error: content " + nid + " not found")
			    .fadeIn('fast')
			    .delay(3000)
			    .fadeOut('slow');
			}
		    }
		});
	    }
	}

    });

})(jQuery);

